import React, { useState, useEffect } from "react";
import axios from "axios";
import {
  FiSearch, FiMapPin, FiStar, FiClock, FiPhone,
  FiFilter, FiUser, FiArrowRight, FiCheckCircle, FiAlertCircle
} from "react-icons/fi";

const API = "http://127.0.0.1:5000";

const SPECIALTIES = [
  "All", "Cardiologist", "Neurologist", "Pulmonologist", "Endocrinologist",
  "Gastroenterologist", "Urologist", "Orthopedic Surgeon", "Dermatologist",
  "Psychiatrist", "General Physician", "Vascular Surgeon", "Rheumatologist",
  "Oncologist", "Gynecologist", "ENT Specialist", "Ophthalmologist"
];

const TIME_SLOTS = ["10:00 AM", "12:00 PM", "3:00 PM", "5:00 PM"];

export default function Doctors() {
  const [doctors, setDoctors]           = useState([]);
  const [filtered, setFiltered]         = useState([]);
  const [loading, setLoading]           = useState(true);
  const [search, setSearch]             = useState("");
  const [specialty, setSpecialty]       = useState("All");
  const [bookingDoctor, setBookingDoctor] = useState(null);
  const [bookingForm, setBookingForm]   = useState({ name: "", phone: "", date: "", time: "" });
  const [bookedSlots, setBookedSlots]   = useState([]);
  const [bookMsg, setBookMsg]           = useState({ text: "", type: "" });
  const [bookingLoading, setBookingLoading] = useState(false);

  // Fetch all doctors on mount
  useEffect(() => {
    fetchAllDoctors();
  }, []);

  const fetchAllDoctors = async (spec = "all") => {
    setLoading(true);
    try {
      const url = spec === "all"
        ? `${API}/api/doctors`
        : `${API}/api/doctors?specialization=${encodeURIComponent(spec)}`;
      const res = await axios.get(url);
      if (res.data && res.data.doctors) {
        setDoctors(res.data.doctors);
        setFiltered(res.data.doctors);
      }
    } catch (err) {
      console.error("Failed to fetch doctors:", err);
    }
    setLoading(false);
  };

  // Filter locally when search changes
  useEffect(() => {
    let list = [...doctors];
    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter(d =>
        d["doctor name"]?.toLowerCase().includes(q) ||
        d.location?.toLowerCase().includes(q) ||
        d.specialization?.toLowerCase().includes(q)
      );
    }
    setFiltered(list);
  }, [search, doctors]);

  // Fetch from API when specialty changes
  useEffect(() => {
    fetchAllDoctors(specialty === "All" ? "all" : specialty);
  }, [specialty]);

  const openBooking = async (doctor) => {
    setBookingDoctor(doctor);
    setBookMsg({ text: "", type: "" });
    setBookingForm({ name: "", phone: "", date: "", time: "" });
    setBookedSlots([]);
  };

  const fetchSlots = async (doctor, date) => {
    if (!date) return;
    try {
      const res = await axios.post(`${API}/booked-slots`, {
        doctor: doctor["doctor name"], date
      });
      setBookedSlots(res.data || []);
    } catch {
      setBookedSlots([]);
    }
  };

  const handleBook = async () => {
    const { name, phone, date, time } = bookingForm;
    if (!name || !phone || !date || !time) {
      setBookMsg({ text: "Please fill all fields", type: "error" });
      return;
    }
    setBookingLoading(true);
    try {
      const res = await axios.post(`${API}/book`, {
        name, phone, date, time,
        doctor: bookingDoctor["doctor name"]
      });
      setBookMsg({ text: res.data.message || "Appointment Confirmed!", type: "success" });
      setTimeout(() => setBookingDoctor(null), 2000);
    } catch (err) {
      setBookMsg({ text: err.response?.data?.error || "Booking failed", type: "error" });
    }
    setBookingLoading(false);
  };

  const sx = {
    page: {
      padding: "24px 28px",
      color: "#e2e8f0",
      fontFamily: "'Inter', sans-serif",
      minHeight: "100vh",
    },
    header: {
      marginBottom: "24px",
    },
    title: {
      fontSize: "22px",
      fontWeight: 600,
      color: "#f1f5f9",
      marginBottom: "4px",
    },
    subtitle: {
      fontSize: "13px",
      color: "#94a3b8",
    },
    controls: {
      display: "flex",
      gap: "12px",
      marginBottom: "20px",
      flexWrap: "wrap",
      alignItems: "center",
    },
    searchBox: {
      display: "flex",
      alignItems: "center",
      gap: "8px",
      background: "#1e293b",
      border: "1px solid #334155",
      borderRadius: "10px",
      padding: "9px 14px",
      flex: 1,
      minWidth: "200px",
    },
    searchInput: {
      background: "transparent",
      border: "none",
      outline: "none",
      color: "#e2e8f0",
      fontSize: "13px",
      flex: 1,
    },
    filterRow: {
      display: "flex",
      gap: "8px",
      flexWrap: "wrap",
    },
    filterBtn: (active) => ({
      padding: "6px 14px",
      borderRadius: "20px",
      border: active ? "1px solid #818cf8" : "1px solid #334155",
      background: active ? "#3730a3" : "#1e293b",
      color: active ? "#c7d2fe" : "#94a3b8",
      fontSize: "12px",
      cursor: "pointer",
      transition: "all .15s",
      fontWeight: active ? 600 : 400,
    }),
    grid: {
      display: "grid",
      gridTemplateColumns: "repeat(auto-fill, minmax(300px, 1fr))",
      gap: "16px",
    },
    card: {
      background: "#1e293b",
      border: "1px solid #334155",
      borderRadius: "14px",
      padding: "18px",
      transition: "border-color .2s",
    },
    cardTop: {
      display: "flex",
      gap: "14px",
      marginBottom: "14px",
      alignItems: "flex-start",
    },
    avatar: {
      width: "46px",
      height: "46px",
      borderRadius: "50%",
      background: "linear-gradient(135deg, #6366f1, #8b5cf6)",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      fontSize: "18px",
      fontWeight: 700,
      color: "#fff",
      flexShrink: 0,
    },
    doctorName: {
      fontSize: "15px",
      fontWeight: 600,
      color: "#f1f5f9",
      marginBottom: "2px",
    },
    specBadge: {
      fontSize: "11px",
      background: "#312e81",
      color: "#a5b4fc",
      borderRadius: "6px",
      padding: "2px 8px",
      display: "inline-block",
    },
    cardInfo: {
      display: "flex",
      flexDirection: "column",
      gap: "6px",
      marginBottom: "14px",
      fontSize: "12px",
      color: "#94a3b8",
    },
    infoRow: {
      display: "flex",
      alignItems: "flex-start",
      gap: "6px",
    },
    stars: (rating) => ({
      color: rating >= 4.5 ? "#fbbf24" : rating >= 4 ? "#f59e0b" : "#d97706",
      fontSize: "12px",
      fontWeight: 600,
    }),
    bookBtn: {
      width: "100%",
      padding: "9px",
      background: "linear-gradient(135deg, #6366f1, #8b5cf6)",
      border: "none",
      borderRadius: "9px",
      color: "#fff",
      fontSize: "13px",
      fontWeight: 600,
      cursor: "pointer",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      gap: "6px",
    },
    empty: {
      textAlign: "center",
      padding: "60px 20px",
      color: "#64748b",
    },
    // Modal
    overlay: {
      position: "fixed",
      inset: 0,
      background: "rgba(0,0,0,0.7)",
      zIndex: 1000,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      padding: "20px",
    },
    modal: {
      background: "#1e293b",
      border: "1px solid #334155",
      borderRadius: "16px",
      padding: "24px",
      width: "100%",
      maxWidth: "420px",
    },
    modalTitle: {
      fontSize: "16px",
      fontWeight: 600,
      color: "#f1f5f9",
      marginBottom: "4px",
    },
    modalSub: {
      fontSize: "12px",
      color: "#94a3b8",
      marginBottom: "20px",
    },
    label: {
      fontSize: "12px",
      color: "#94a3b8",
      marginBottom: "5px",
      display: "block",
    },
    input: {
      width: "100%",
      background: "#0f172a",
      border: "1px solid #334155",
      borderRadius: "8px",
      padding: "9px 12px",
      color: "#e2e8f0",
      fontSize: "13px",
      marginBottom: "12px",
      outline: "none",
      boxSizing: "border-box",
    },
    slotsGrid: {
      display: "grid",
      gridTemplateColumns: "repeat(2, 1fr)",
      gap: "8px",
      marginBottom: "16px",
    },
    slotBtn: (selected, booked) => ({
      padding: "9px",
      borderRadius: "8px",
      border: selected ? "1px solid #6366f1" : "1px solid #334155",
      background: booked ? "#1e1e2e" : selected ? "#3730a3" : "#0f172a",
      color: booked ? "#475569" : selected ? "#c7d2fe" : "#94a3b8",
      fontSize: "12px",
      cursor: booked ? "not-allowed" : "pointer",
      textDecoration: booked ? "line-through" : "none",
    }),
    confirmBtn: {
      width: "100%",
      padding: "11px",
      background: "linear-gradient(135deg, #6366f1, #8b5cf6)",
      border: "none",
      borderRadius: "10px",
      color: "#fff",
      fontSize: "14px",
      fontWeight: 600,
      cursor: "pointer",
      marginBottom: "8px",
    },
    cancelBtn: {
      width: "100%",
      padding: "9px",
      background: "transparent",
      border: "1px solid #334155",
      borderRadius: "10px",
      color: "#94a3b8",
      fontSize: "13px",
      cursor: "pointer",
    },
    msgBox: (type) => ({
      padding: "10px 12px",
      borderRadius: "8px",
      background: type === "success" ? "#052e16" : "#450a0a",
      color: type === "success" ? "#4ade80" : "#f87171",
      fontSize: "13px",
      marginBottom: "12px",
      display: "flex",
      alignItems: "center",
      gap: "6px",
    }),
  };

  const getInitials = (name) =>
    name ? name.split(" ").map(w => w[0]).join("").slice(0, 2).toUpperCase() : "DR";

  return (
    <div style={sx.page}>
      <div style={sx.header}>
        <h2 style={sx.title}>Doctors List</h2>
        <p style={sx.subtitle}>Browse and book appointments with specialists near you</p>
      </div>

      {/* Search */}
      <div style={sx.controls}>
        <div style={sx.searchBox}>
          <FiSearch size={15} color="#64748b" />
          <input
            style={sx.searchInput}
            placeholder="Search by name, specialty or location..."
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
        </div>
      </div>

      {/* Specialty filter */}
      <div style={sx.filterRow}>
        {SPECIALTIES.map(s => (
          <button
            key={s}
            style={sx.filterBtn(specialty === s)}
            onClick={() => setSpecialty(s)}
          >
            {s}
          </button>
        ))}
      </div>

      <div style={{ margin: "16px 0", fontSize: "13px", color: "#64748b" }}>
        {filtered.length} doctor{filtered.length !== 1 ? "s" : ""} found
      </div>

      {/* Doctors grid */}
      {loading ? (
        <div style={sx.empty}>Loading doctors...</div>
      ) : filtered.length === 0 ? (
        <div style={sx.empty}>
          <FiUser size={40} style={{ marginBottom: "12px", opacity: 0.4 }} />
          <p style={{ fontSize: "15px", fontWeight: 600, marginBottom: "4px" }}>No doctors found</p>
          <p style={{ fontSize: "13px" }}>Try a different specialty or search term</p>
        </div>
      ) : (
        <div style={sx.grid}>
          {filtered.map((doc, i) => (
            <div key={i} style={sx.card}>
              <div style={sx.cardTop}>
                <div style={sx.avatar}>{getInitials(doc["doctor name"])}</div>
                <div>
                  <div style={sx.doctorName}>{doc["doctor name"]}</div>
                  <span style={sx.specBadge}>{doc.specialization}</span>
                </div>
              </div>

              <div style={sx.cardInfo}>
                <div style={sx.infoRow}>
                  <FiMapPin size={12} style={{ marginTop: "1px", flexShrink: 0 }} />
                  <span>{doc.location}</span>
                </div>
                <div style={sx.infoRow}>
                  <FiStar size={12} style={{ marginTop: "1px", flexShrink: 0 }} />
                  <span style={sx.stars(doc.rating)}>{doc.rating} ★</span>
                  <span style={{ marginLeft: "4px" }}>rating</span>
                </div>
                <div style={sx.infoRow}>
                  <FiClock size={12} style={{ marginTop: "1px", flexShrink: 0 }} />
                  <span>{doc.availability || "Available"}</span>
                </div>
              </div>

              <button style={sx.bookBtn} onClick={() => openBooking(doc)}>
                Book Appointment <FiArrowRight size={14} />
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Booking Modal */}
      {bookingDoctor && (
        <div style={sx.overlay} onClick={(e) => e.target === e.currentTarget && setBookingDoctor(null)}>
          <div style={sx.modal}>
            <div style={sx.modalTitle}>{bookingDoctor["doctor name"]}</div>
            <div style={sx.modalSub}>{bookingDoctor.specialization} · {bookingDoctor.location}</div>

            {bookMsg.text && (
              <div style={sx.msgBox(bookMsg.type)}>
                {bookMsg.type === "success" ? <FiCheckCircle size={14} /> : <FiAlertCircle size={14} />}
                {bookMsg.text}
              </div>
            )}

            <label style={sx.label}>Patient Name *</label>
            <input
              style={sx.input}
              placeholder="Your full name"
              value={bookingForm.name}
              onChange={e => setBookingForm({ ...bookingForm, name: e.target.value })}
            />

            <label style={sx.label}>Phone *</label>
            <input
              style={sx.input}
              placeholder="Your phone number"
              value={bookingForm.phone}
              onChange={e => setBookingForm({ ...bookingForm, phone: e.target.value })}
            />

            <label style={sx.label}>Date *</label>
            <input
              style={sx.input}
              type="date"
              min={new Date().toISOString().split("T")[0]}
              value={bookingForm.date}
              onChange={e => {
                setBookingForm({ ...bookingForm, date: e.target.value, time: "" });
                fetchSlots(bookingDoctor, e.target.value);
              }}
            />

            <label style={sx.label}>Time Slot *</label>
            <div style={sx.slotsGrid}>
              {TIME_SLOTS.map(slot => {
                const booked   = bookedSlots.includes(slot);
                const selected = bookingForm.time === slot;
                return (
                  <button
                    key={slot}
                    style={sx.slotBtn(selected, booked)}
                    disabled={booked}
                    onClick={() => !booked && setBookingForm({ ...bookingForm, time: slot })}
                  >
                    {slot} {booked ? "(Booked)" : ""}
                  </button>
                );
              })}
            </div>

            <button
              style={sx.confirmBtn}
              onClick={handleBook}
              disabled={bookingLoading}
            >
              {bookingLoading ? "Confirming..." : "Confirm Booking"}
            </button>
            <button style={sx.cancelBtn} onClick={() => setBookingDoctor(null)}>
              Cancel
            </button>
          </div>
        </div>
      )}
    </div>
  );
}