import React, { useState, useEffect } from "react";
import axios from "axios";
import {
  FiFileText, FiDownload, FiClock, FiActivity,
  FiAlertCircle, FiCheckCircle, FiUser, FiCalendar,
  FiTrendingUp, FiHeart, FiZap
} from "react-icons/fi";
import { Link } from "react-router-dom";

const API = "http://127.0.0.1:5000";

const URGENCY_COLOR = {
  EMERGENCY: { bg: "#450a0a", color: "#f87171", label: "Emergency" },
  HIGH:      { bg: "#431407", color: "#fb923c", label: "High Priority" },
  MEDIUM:    { bg: "#1c1917", color: "#fbbf24", label: "Medium Priority" },
  LOW:       { bg: "#052e16", color: "#4ade80", label: "Low Priority" },
};

export default function Reports() {
  const [history, setHistory]       = useState([]);
  const [appointments, setAppointments] = useState([]);
  const [pdfLoading, setPdfLoading] = useState(null);
  const [activeTab, setActiveTab]   = useState("predictions");

  useEffect(() => {
    // Load prediction history from localStorage
    const stored = JSON.parse(localStorage.getItem("history") || "[]");
    setHistory(stored.slice(-20).reverse());

    // Load appointments
    fetchAppointments();
  }, []);

  const fetchAppointments = async () => {
    // Appointments are stored locally — no dedicated GET all endpoint
    const stored = JSON.parse(localStorage.getItem("appointments") || "[]");
    setAppointments(stored);
  };

  const downloadPDF = async (appt) => {
    setPdfLoading(appt.doctor + appt.date);
    try {
      const res = await axios.post(`${API}/generate-pdf`, {
        name:   appt.patient_name || appt.name || "Patient",
        phone:  appt.phone || "N/A",
        doctor: appt.doctor,
        date:   appt.date,
        time:   appt.time,
      }, { responseType: "blob" });

      const url  = window.URL.createObjectURL(new Blob([res.data]));
      const link = document.createElement("a");
      link.href  = url;
      link.setAttribute("download", `appointment_${appt.doctor}_${appt.date}.pdf`);
      document.body.appendChild(link);
      link.click();
      link.remove();
    } catch (err) {
      console.error("PDF generation failed:", err);
    }
    setPdfLoading(null);
  };

  const clearHistory = () => {
    localStorage.removeItem("history");
    setHistory([]);
  };

  const sx = {
    page: {
      padding: "24px 28px",
      color: "#e2e8f0",
      fontFamily: "'Inter', sans-serif",
      minHeight: "100vh",
    },
    header: {
      marginBottom: "24px",
    },
    title: {
      fontSize: "22px",
      fontWeight: 600,
      color: "#f1f5f9",
      marginBottom: "4px",
    },
    subtitle: {
      fontSize: "13px",
      color: "#94a3b8",
    },
    tabs: {
      display: "flex",
      gap: "4px",
      marginBottom: "24px",
      background: "#0f172a",
      borderRadius: "10px",
      padding: "4px",
      width: "fit-content",
    },
    tab: (active) => ({
      padding: "8px 20px",
      borderRadius: "8px",
      border: "none",
      background: active ? "#1e293b" : "transparent",
      color: active ? "#f1f5f9" : "#64748b",
      fontSize: "13px",
      fontWeight: active ? 600 : 400,
      cursor: "pointer",
      transition: "all .15s",
    }),
    statsRow: {
      display: "grid",
      gridTemplateColumns: "repeat(auto-fit, minmax(150px, 1fr))",
      gap: "12px",
      marginBottom: "24px",
    },
    statCard: {
      background: "#1e293b",
      border: "1px solid #334155",
      borderRadius: "12px",
      padding: "16px",
    },
    statNum: {
      fontSize: "24px",
      fontWeight: 700,
      color: "#f1f5f9",
      marginBottom: "2px",
    },
    statLabel: {
      fontSize: "12px",
      color: "#64748b",
    },
    card: {
      background: "#1e293b",
      border: "1px solid #334155",
      borderRadius: "14px",
      padding: "18px",
      marginBottom: "12px",
    },
    cardHeader: {
      display: "flex",
      justifyContent: "space-between",
      alignItems: "flex-start",
      marginBottom: "12px",
    },
    diseaseName: {
      fontSize: "15px",
      fontWeight: 600,
      color: "#f1f5f9",
    },
    urgencyBadge: (urgency) => ({
      fontSize: "11px",
      padding: "3px 10px",
      borderRadius: "20px",
      background: URGENCY_COLOR[urgency]?.bg || "#1e293b",
      color: URGENCY_COLOR[urgency]?.color || "#94a3b8",
      fontWeight: 600,
    }),
    metaRow: {
      display: "flex",
      gap: "16px",
      flexWrap: "wrap",
      fontSize: "12px",
      color: "#64748b",
      marginBottom: "10px",
    },
    metaItem: {
      display: "flex",
      alignItems: "center",
      gap: "4px",
    },
    confBar: {
      height: "6px",
      background: "#0f172a",
      borderRadius: "3px",
      overflow: "hidden",
      marginTop: "8px",
    },
    confFill: (conf) => ({
      height: "100%",
      width: `${conf}%`,
      background: conf >= 70 ? "#6366f1" : conf >= 50 ? "#f59e0b" : "#64748b",
      borderRadius: "3px",
      transition: "width .5s",
    }),
    symptomsBox: {
      background: "#0f172a",
      borderRadius: "8px",
      padding: "8px 12px",
      fontSize: "12px",
      color: "#94a3b8",
      marginTop: "10px",
    },
    downloadBtn: {
      display: "flex",
      alignItems: "center",
      gap: "6px",
      padding: "8px 16px",
      background: "linear-gradient(135deg, #6366f1, #8b5cf6)",
      border: "none",
      borderRadius: "8px",
      color: "#fff",
      fontSize: "12px",
      fontWeight: 600,
      cursor: "pointer",
      marginTop: "12px",
    },
    statusBadge: (status) => ({
      fontSize: "11px",
      padding: "2px 8px",
      borderRadius: "20px",
      background: status === "Confirmed" ? "#052e16" :
                  status === "Cancelled" ? "#450a0a" : "#1c1917",
      color: status === "Confirmed" ? "#4ade80" :
             status === "Cancelled" ? "#f87171" : "#fbbf24",
      fontWeight: 600,
    }),
    empty: {
      textAlign: "center",
      padding: "60px 20px",
      color: "#64748b",
    },
    clearBtn: {
      fontSize: "12px",
      padding: "6px 14px",
      background: "transparent",
      border: "1px solid #334155",
      borderRadius: "8px",
      color: "#64748b",
      cursor: "pointer",
    },
  };

  // Stats
  const emergencyCount = history.filter(h => h.urgency === "EMERGENCY").length;
  const highCount      = history.filter(h => h.urgency === "HIGH").length;
  const avgConf        = history.length > 0
    ? Math.round(history.reduce((a, h) => a + (h.confidence || 0), 0) / history.length)
    : 0;

  return (
    <div style={sx.page}>
      <div style={sx.header}>
        <h2 style={sx.title}>Health Reports</h2>
        <p style={sx.subtitle}>Your complete diagnosis history and appointment reports</p>
      </div>

      {/* Tabs */}
      <div style={sx.tabs}>
        <button style={sx.tab(activeTab === "predictions")} onClick={() => setActiveTab("predictions")}>
          <FiActivity size={13} style={{ marginRight: "5px" }} />
          Predictions ({history.length})
        </button>
        <button style={sx.tab(activeTab === "appointments")} onClick={() => setActiveTab("appointments")}>
          <FiCalendar size={13} style={{ marginRight: "5px" }} />
          Appointments ({appointments.length})
        </button>
      </div>

      {/* ── PREDICTIONS TAB ── */}
      {activeTab === "predictions" && (
        <>
          {/* Stats */}
          {history.length > 0 && (
            <div style={sx.statsRow}>
              <div style={sx.statCard}>
                <div style={sx.statNum}>{history.length}</div>
                <div style={sx.statLabel}>Total analyses</div>
              </div>
              <div style={sx.statCard}>
                <div style={{ ...sx.statNum, color: "#fb923c" }}>{emergencyCount}</div>
                <div style={sx.statLabel}>Emergency alerts</div>
              </div>
              <div style={sx.statCard}>
                <div style={{ ...sx.statNum, color: "#fbbf24" }}>{highCount}</div>
                <div style={sx.statLabel}>High priority</div>
              </div>
              <div style={sx.statCard}>
                <div style={{ ...sx.statNum, color: "#6366f1" }}>{avgConf}%</div>
                <div style={sx.statLabel}>Avg confidence</div>
              </div>
            </div>
          )}

          {/* History list */}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "12px" }}>
            <span style={{ fontSize: "13px", color: "#64748b" }}>
              {history.length} diagnosis report{history.length !== 1 ? "s" : ""}
            </span>
            {history.length > 0 && (
              <button style={sx.clearBtn} onClick={clearHistory}>Clear history</button>
            )}
          </div>

          {history.length === 0 ? (
            <div style={sx.empty}>
              <FiFileText size={44} style={{ marginBottom: "12px", opacity: 0.4 }} />
              <p style={{ fontSize: "15px", fontWeight: 600, marginBottom: "6px" }}>No reports yet</p>
              <p style={{ fontSize: "13px", marginBottom: "16px" }}>
                Complete a diagnosis in the AI Assistant to generate reports
              </p>
              <Link to="/assistant" style={{
                display: "inline-flex", alignItems: "center", gap: "6px",
                padding: "9px 18px", background: "linear-gradient(135deg, #6366f1, #8b5cf6)",
                borderRadius: "10px", color: "#fff", textDecoration: "none",
                fontSize: "13px", fontWeight: 600
              }}>
                <FiZap size={14} /> Start Diagnosis
              </Link>
            </div>
          ) : (
            history.map((item, i) => {
              const urgency = item.urgency || "LOW";
              return (
                <div key={i} style={sx.card}>
                  <div style={sx.cardHeader}>
                    <div>
                      <div style={sx.diseaseName}>{item.disease || "Unknown"}</div>
                      <div style={{ fontSize: "12px", color: "#64748b", marginTop: "2px" }}>
                        {item.specialist && `Specialist: ${item.specialist}`}
                      </div>
                    </div>
                    <span style={sx.urgencyBadge(urgency)}>
                      {URGENCY_COLOR[urgency]?.label || urgency}
                    </span>
                  </div>

                  <div style={sx.metaRow}>
                    <div style={sx.metaItem}>
                      <FiClock size={11} /> {item.date || "Unknown date"}
                    </div>
                    <div style={sx.metaItem}>
                      <FiTrendingUp size={11} /> {item.confidence || 0}% confidence
                    </div>
                  </div>

                  <div style={sx.confBar}>
                    <div style={sx.confFill(item.confidence || 0)} />
                  </div>

                  {item.symptoms && (
                    <div style={sx.symptomsBox}>
                      <strong>Symptoms:</strong> {item.symptoms}
                    </div>
                  )}
                </div>
              );
            })
          )}
        </>
      )}

      {/* ── APPOINTMENTS TAB ── */}
      {activeTab === "appointments" && (
        <>
          {appointments.length === 0 ? (
            <div style={sx.empty}>
              <FiCalendar size={44} style={{ marginBottom: "12px", opacity: 0.4 }} />
              <p style={{ fontSize: "15px", fontWeight: 600, marginBottom: "6px" }}>No appointments yet</p>
              <p style={{ fontSize: "13px", marginBottom: "16px" }}>
                Book an appointment through the AI Assistant or Doctors page
              </p>
              <Link to="/doctors" style={{
                display: "inline-flex", alignItems: "center", gap: "6px",
                padding: "9px 18px", background: "linear-gradient(135deg, #6366f1, #8b5cf6)",
                borderRadius: "10px", color: "#fff", textDecoration: "none",
                fontSize: "13px", fontWeight: 600
              }}>
                <FiUser size={14} /> Find Doctors
              </Link>
            </div>
          ) : (
            appointments.map((appt, i) => (
              <div key={i} style={sx.card}>
                <div style={sx.cardHeader}>
                  <div>
                    <div style={sx.diseaseName}>{appt.doctor}</div>
                    <div style={{ fontSize: "12px", color: "#64748b", marginTop: "2px" }}>
                      Patient: {appt.patient_name || appt.name}
                    </div>
                  </div>
                  <span style={sx.statusBadge(appt.status)}>{appt.status}</span>
                </div>

                <div style={sx.metaRow}>
                  <div style={sx.metaItem}>
                    <FiCalendar size={11} /> {appt.date}
                  </div>
                  <div style={sx.metaItem}>
                    <FiClock size={11} /> {appt.time}
                  </div>
                  {appt.phone && (
                    <div style={sx.metaItem}>
                      <FiUser size={11} /> {appt.phone}
                    </div>
                  )}
                </div>

                {appt.status !== "Cancelled" && (
                  <button
                    style={sx.downloadBtn}
                    onClick={() => downloadPDF(appt)}
                    disabled={pdfLoading === appt.doctor + appt.date}
                  >
                    <FiDownload size={13} />
                    {pdfLoading === appt.doctor + appt.date ? "Generating..." : "Download PDF"}
                  </button>
                )}
              </div>
            ))
          )}
        </>
      )}
    </div>
  );
}