import React, { useState } from "react";
import "./App.css";
import Login from "./components/Login";
import strings from "./strings";

import Chatbox from "./Chatbox";
import SymptomForm from "./SymptomForm";
import Reports from "./components/Reports";
import Home from "./components/Home";
import Settings from "./components/Settings";
import NewsPanel from "./components/NewsPanel";
import Doctors from "./components/Doctors";
import { BrowserRouter as Router, Routes, Route, Link, useLocation } from "react-router-dom";

// Icons
import {
  FiHome, FiActivity, FiClock, FiUsers,
  FiFileText, FiSettings, FiLogOut, FiZap,
  FiHeart, FiBriefcase, FiLayers
} from "react-icons/fi";
import { MdOutlineHealing, MdMonitorHeart } from "react-icons/md";
import { HiOutlineSparkles, HiOutlineCubeTransparent } from "react-icons/hi2";
import { RiHealthBookLine } from "react-icons/ri";
import { TbStethoscope } from "react-icons/tb";

function AppContent({ user, setUser, history }) {
  const location = useLocation();

  const navItems = [
    { path: "/",           icon: <FiLayers size={19} />,     label: strings.navHome, color: "var(--primary)" },
    { path: "/assistant",  icon: <TbStethoscope size={19} />, label: strings.navAssistant, color: "var(--sky)" },
    { path: "/predictions",icon: <FiBriefcase size={19} />,    label: strings.navPredictions, color: "var(--amber)" },
    { path: "/news",       icon: <FiActivity size={19} />,   label: "Medical News", color: "var(--emerald)" },
    { path: "/doctors",    icon: <MdMonitorHeart size={19} />,    label: strings.navDoctors, color: "var(--rose)" },
    { path: "/reports",    icon: <RiHealthBookLine size={19} />, label: strings.navReports, color: "var(--secondary)" },
    { path: "/settings",   icon: <FiSettings size={19} />, label: strings.navSettings, color: "var(--indigo)" },
  ];

  const currentItem = navItems.find(n => n.path === location.pathname) || navItems[0];

  const getInitials = (name) => {
    if (!name) return "U";
    return name.split(" ").map(n => n[0]).join("").toUpperCase().slice(0, 2);
  };

  return (
    <div className="app-container">

      {/* ── Sidebar ── */}
      <div className="sidebar">
        <div className="logo">
          <div className="logo-icon">
            <MdOutlineHealing size={20} color="#fff" />
          </div>
          <span className="logo-text">{strings.appLogo}</span>
        </div>

        <p className="nav-section-label">{strings.navSectionNavigation || "Navigation"}</p>
        <ul>
          {navItems.slice(0, 7).map(item => (
            <li key={item.path} className={location.pathname === item.path ? "active-link" : ""}>
              <Link to={item.path}>
                <span className="nav-icon" style={{ color: item.color }}>{item.icon}</span>
                {item.label}
              </Link>
            </li>
          ))}
        </ul>

        <p className="nav-section-label" style={{ marginTop: "18px" }}>{strings.navSectionAccount || "Account"}</p>
        <ul>
          <li className={location.pathname === "/settings" ? "active-link" : ""}>
            <Link to="/settings">
              <span className="nav-icon"><FiSettings size={18} /></span>
              {strings.navSettings}
            </Link>
          </li>
        </ul>

        <div className="sidebar-footer">
          <div className="sidebar-user">
            <div className="sidebar-user-avatar">{getInitials(user?.name)}</div>
            <span className="sidebar-user-name">{user?.name || "User"}</span>
          </div>
        </div>
      </div>

      {/* ── Main Content ── */}
      <div className="main-content">

        {/* Topbar */}
        <div className="navbar">
          <div className="navbar-left">
            <h1>{currentItem.label}</h1>
            <span className="navbar-breadcrumb">MediGuide / {currentItem.label}</span>
          </div>

          <div className="user-profile">
            <div className="user-info-pill">
              <div className="user-avatar-sm">{getInitials(user?.name)}</div>
              <span>{user?.name || "User"}</span>
            </div>
            <button onClick={() => setUser(null)} className="logout-btn">
              <FiLogOut size={14} /> {strings.logout}
            </button>
          </div>
        </div>

        {/* Pages */}
        <div className="page-wrapper">
          <Routes>

            {/* Dashboard / Home */}
            <Route path="/" element={<Home />} />

            {/* AI Assistant */}
            <Route
              path="/assistant"
              element={
                <div className="assistant-layout">
                  <div className="left-panel">
                    <SymptomForm />
                  </div>
                  <div className="right-panel">
                    <Chatbox />
                  </div>
                </div>
              }
            />

            {/* Predictions History */}
            <Route
              path="/predictions"
              element={
                <div className="predictions-page">
                  <h2 className="page-title">{strings.predictionHistoryTitle}</h2>
                  <p className="page-subtitle">Your recent AI-powered health analyses</p>

                  {history.length === 0 ? (
                    <div className="no-data-card">
                      <FiActivity size={52} className="no-data-icon" color="var(--text-muted)" />
                      <p className="no-data-title">No predictions yet</p>
                      <p className="no-data-desc">{strings.noPredictions}</p>
                      <Link to="/assistant" className="cta-btn" style={{ textDecoration: "none", marginTop: "4px" }}>
                        <FiZap size={15} /> Start Diagnosis
                      </Link>
                    </div>
                  ) : (
                    <div className="history-grid">
                      {history.slice(-10).reverse().map((item, index) => (
                        <div key={index} className="history-card">
                          <div className="history-header">
                            <span className="case-id">{strings.caseIdPrefix}{index + 1}</span>
                            <span className="date">
                              <FiClock size={11} /> {item.date}
                            </span>
                          </div>

                          <div className="symptoms">
                            <p className="symptoms-label">{strings.symptomsLabel}</p>
                            <p className="symptoms-text">{item.symptoms}</p>
                          </div>

                          <div className="symptoms" style={{ marginTop: "14px", paddingTop: "14px", borderTop: "1px solid var(--glass-border)" }}>
                            <p className="symptoms-label">{strings.resultLabel}</p>
                            <p className="disease-name">{item.disease}</p>
                          </div>

                          <div className="actions">
                            <button className="view-btn">{strings.viewDetails}</button>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              }
            />

            {/* Doctors */}
            <Route
              path="/doctors"
              element={<Doctors />}
            />

            {/* Reports */}
            <Route path="/reports" element={<Reports />} />

            {/* Medical News */}
            <Route path="/news" element={<NewsPanel />} />

            {/* Settings */}
            <Route path="/settings" element={<Settings />} />

          </Routes>
        </div>
      </div>
    </div>
  );
}

function App() {
  const [user, setUser] = useState(() => {
    const saved = localStorage.getItem("user_session");
    return saved ? JSON.parse(saved) : null;
  });

  const handleSetUser = (u) => {
    setUser(u);
    if (u) {
      localStorage.setItem("user_session", JSON.stringify(u));
    } else {
      localStorage.removeItem("user_session");
    }
  };

  if (!user) {
    return <Login setUser={handleSetUser} />;
  }

  const history = JSON.parse(localStorage.getItem("history") || "[]");

  return (
    <Router>
      <AppContent user={user} setUser={handleSetUser} history={history} />
    </Router>
  );
}

export default App;